import{_ as e,o as i,a as s,b as c}from"./app.C41L12d5.js";const t="/ascendc.github.io/assets/simt_mem.B-cO7k_Z.png",l="/ascendc.github.io/assets/simt_ub.CycysjF4.png",n="/ascendc.github.io/assets/simt_layout.C9eOyrNq.png",r="/ascendc.github.io/assets/simt_path.CXTPYD80.png",u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"高级AI Core编程模型","link":"/guide/programming_guide/advanced_programming/advanced_ai_core_programming_model/advanced_ai_core_programming_model"},{"text":"SIMD与SIMT混合编程","link":"/guide/programming_guide/advanced_programming/advanced_ai_core_programming_model/simd_simt_hybrid_programming/overview"},{"text":"内存层级","link":"/guide/programming_guide/advanced_programming/advanced_ai_core_programming_model/simd_simt_hybrid_programming/memory_hierarchy"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/advanced_ai_core_programming_model/simd_simt_hybrid_programming/memory_hierarchy.md","filePath":"guide/programming_guide/advanced_programming/advanced_ai_core_programming_model/simd_simt_hybrid_programming/memory_hierarchy.md","outlineHeaders":[{"level":2,"title":"整体内存资源","slug":"整体内存资源","link":"#整体内存资源"},{"level":2,"title":"UB划分","slug":"UB划分","link":"#UB划分"},{"level":3,"title":"内存空间说明","slug":"内存空间说明","link":"#内存空间说明"},{"level":2,"title":"数据通路","slug":"数据通路","link":"#数据通路"},{"level":3,"title":"访问UB内存","slug":"访问UB内存","link":"#访问UB内存"},{"level":3,"title":"访问GM内存","slug":"访问GM内存","link":"#访问GM内存"}],"lastUpdated":1787050286000}'),p={name:"guide/programming_guide/advanced_programming/advanced_ai_core_programming_model/simd_simt_hybrid_programming/memory_hierarchy.md"};function o(h,a,d,_,g,m){return i(),s("div",null,[...a[0]||(a[0]=[c('<div><article class="markdown-body"><h1>内存层级</h1><h2 id="整体内存资源">整体内存资源<span id="zh-cn_topic_0000002571695539_section598391912124"></span><a class="header-anchor" href="#整体内存资源">​</a></h2><p>在SIMD与SIMT混合编程场景下，整体内存资源如下图所示。核外的Global Memory是所有核的全局内存，容量最大，但访问效率最低。AIC的L1和AIV的Unified Buffer（UB）是单核内的共享内存，容量较小，但访问效率较高。私有内存层最靠近计算单元，容量最小，访问效率最高。</p><p><strong>图1</strong> SIMD与SIMT混合编程内存层级<br><img src="'+t+'" alt="内存层级" style="width:70%;height:auto;"></p><p>在混合编程场景下，UB内存是SIMT VF和SIMD VF的共享内存。Vector Function切换时，UB上的数据不会被清除，因此可通过UB实现Vector Function间的通信。下文<a href="#ub%E5%88%92%E5%88%86">UB划分</a>章节详细说明UB如何划分为静态内存、动态内存、Data Cache等区域；<a href="#%E6%95%B0%E6%8D%AE%E9%80%9A%E8%B7%AF">数据通路</a>章节介绍混合编程场景下的整体数据通路，并说明并行流水间的数据同步和访问GM时的缓存一致性问题。</p><h2 id="UB划分">UB划分<span id="ZH-CN_TOPIC_0000002563309890"></span><a class="header-anchor" href="#UB划分">​</a></h2><p>UB内存空间总大小为256KB。UB按功能划分为四个主要区域，从低地址到高地址依次为静态内存、动态内存、预留空间和Data Cache，如下图所示。</p><p><strong>图2</strong> SIMD与SIMT混合编程UB内存分配<br><img src="'+l+`" alt title="UB内存分配图"></p><h3 id="内存空间说明">内存空间说明<span id="zh-cn_topic_0000002571697985_section19291134194"></span><a class="header-anchor" href="#内存空间说明">​</a></h3><ol><li><p>静态内存：从内存的起始地址分配一段指定大小的内存空间，其大小在编译时确定，不可动态修改。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 静态内存通过数组分配，例如：</span>
<span class="n">__ubuf__</span><span class="w"> </span><span class="kt">char</span><span class="w"> </span><span class="n">static_buf</span><span class="p">[</span><span class="mi">1024</span><span class="p">];</span>
</code></pre></div></li><li><p>动态内存：位于静态内存之后，其大小由<a href="kernel_and_vf_functions.html#zh-cn_topic_0000002571578013_section156822920311">&lt;&lt;&lt;...&gt;&gt;&gt;</a>中的<code>dyn_ub_size</code>参数指定，可通过以下方式申请使用。</p><ul><li><p>使用动态数组分配。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 动态内存通过动态数组分配，例如：</span>
<span class="k">extern</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">char</span><span class="w"> </span><span class="n">dynamic_buf</span><span class="p">[];</span>
</code></pre></div></li><li><p>通过LocalMemAllocator的Alloc接口申请。</p></li></ul><p>由于动态内存均从静态内存结束位置之后开始分配，因此只能选择其中一种方式申请动态内存，否则可能导致地址空间重叠，从而引发未定义行为。</p></li><li><p>预留空间：编译器和Ascend C的预留空间，大小固定为8KB。</p></li><li><p>Data Cache：SIMT专有的Data Cache空间，可分配的内存大小范围为32KB到128KB，具体计算公式如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>Data Cache空间大小 = min(UB总大小（256KB） - 静态内存 - 动态内存 - 预留空间（8KB）, 128KB)
</code></pre></div><p>Data Cache作为访问GM内存的缓存，其大小会影响算子的访存效率。若Data Cache小于32KB，执行时会出现校验报错并退出，因此申请内存时需确保预留足够的Data Cache空间。</p></li></ol><p>由于Data Cache、预留空间与用户申请的UB内存共用同一块UB，因此开发者无法使用全部UB空间，应确保SIMT和SIMD各个执行空间中的实际UB访问范围都不超过已申请的静态内存和动态内存大小。</p><p>静态内存和动态内存的声明或配置限定了用户使用UB内存的有效范围。若用户配置的内存大小不足，甚至未申请内存即直接访问UB地址，访问地址可能越过用户动、静态内存边界并落入Data Cache区域。由于Data Cache容量由UB总量扣除静态内存、动态内存和预留空间后确定，所以用户共享内存配置偏小会扩大可分配给Data Cache的剩余空间。当程序执行越过已申请的动、静态内存边界，发生越界写入行为时，未必立即表现为内存分配失败，但可能破坏SIMT全局内存访问的数据缓存，导致计算结果不稳定或算子精度异常。</p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>用户可选择禁用预留空间，禁用方法为：编译时增加<a href="../../../compilation_and_execution/operator_compilation/ai_core_operator_compilation.html#ZH-CN_TOPIC_0000002462746461">--cce-disable-vf-stack-reserved-ubuf</a>选项。开启该选项后，编译器不再预留该部分UB空间，该空间可作为普通UB空间使用，Data Cache空间可按如下公式估算：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>Data Cache空间大小 = min(UB总大小（256KB） - 静态内存 - 动态内存 - 预留空间（8KB）, 128KB)
</code></pre></div><p>使用该选项时，仍需保证Data Cache空间不小于32KB，且Data Cache空间上限仍为128KB。开启该选项后，编译器将无法使用预留UB空间作为寄存器溢出的缓存空间，开发者需保证不会发生寄存器溢出。</p></div><p>混合编程模式下，可在SIMT VF、SIMD VF和MainScalar执行空间申请静态内存和动态内存。MainScalar是指Device侧在VF函数外部的执行空间。下图为不同执行空间申请内存时对应的UB内存排布示意图。</p><p><strong>图3</strong> 不同执行空间的UB内存排布<br><img src="`+n+'" alt="内存排布" style="width:80%;height:auto;"></p><p>用户在申请静态内存和动态内存时需要注意：</p><ul><li>多次申请的静态内存在UB上按一定的首地址对齐规则排布： <ul><li>默认情况下，申请到的静态内存首地址按照32B对齐；</li><li>支持用户使用<code>__align__(N)</code>手动指定对齐，优先级高于默认对齐。</li></ul></li><li>动态内存大小在<code>&lt;&lt;&lt;...&gt;&gt;&gt;</code>执行时动态配置，全局只有一份，因此不同执行位置申请的动态内存返回的首地址均相同。</li></ul><h2 id="数据通路">数据通路<a class="header-anchor" href="#数据通路">​</a></h2><p>混合编程场景下，AIV核支持在SIMT VF、SIMD VF和MainScalar执行空间访问UB/GM，同时支持独立的UB到GM的MTE通路。整体数据通路如下图所示。</p><p><strong>图4</strong> SIMD与SIMT混合编程数据通路<br><img src="'+r+'" alt="SIMD与SIMT混合编程数据通路" style="width:90%;height:auto;"></p><h3 id="访问UB内存">访问UB内存<a class="header-anchor" href="#访问UB内存">​</a></h3><p>对于UB内存，VF内读写UB使用Vector流水，MainScalar上读写UB使用Scalar流水，同时还存在UB与GM之间的MTE流水。由于这三条流水并行执行，若流水间存在数据依赖，需要做好同步。</p><h3 id="访问GM内存">访问GM内存<a class="header-anchor" href="#访问GM内存">​</a></h3><p>对于GM内存，SIMT VF和MainScalar对GM的读写会经过各自的Data Cache；同时，MTE流水也可能引发缓存数据一致性问题，具体如下：</p><ul><li>在SIMT VF执行空间读GM上的数据时，可能存在缓存数据不一致的问题： <ul><li>写数据时，底层会确保数据立即写出到GM，从而确保其他通路读取到最新数据；</li><li>读数据时，默认访存的底层实现与<a href="../../../../../api/SIMT-API/memory_access_functions/asc_ldca.html">asc_ldca</a>的实现一致。若访问的内存数据在SIMT Data Cache中命中，默认会读取Cache数据，可能导致读取到的数据与GM中的最新数据不一致。</li></ul></li><li>在MainScalar执行空间通过Cache读写GM上的数据时，读写均可能存在一致性问题： <ul><li>写数据时，数据会先写入Cache，底层无法保证数据立即刷新到GM上，此时其他通路读取到的可能是旧数据。可使用缓存控制使数据立即刷新到GM上，保证其它通路读到的是最新数据，具体详见<a href="../../../../../api/SIMD-API/c_api/cache_ctrl/asc_dcci.html">asc_dcci</a>中的内容；</li><li>读数据时，若访问的内存在Cache中命中，将不会读取GM中的最新数据，可能导致读取到的数据失效。</li></ul></li></ul><p>在SIMT VF执行空间读GM上的数据时，对于上述缓存数据与GM数据不一致的问题，可以通过以下的方式解决：</p><ul><li>可使用<code>volatile</code>关键字声明指针或者变量以获取最新数据。</li><li>可使用<a href="../../../../../api/SIMT-API/memory_access_functions/asc_dcci_single.html">asc_dcci_single</a>接口刷新指定地址所在的Cache Line，使用<a href="../../../../../api/SIMT-API/memory_access_functions/asc_dcci_entire.html">asc_dcci_entire</a>接口刷新核内整个Data Cache。</li><li>可使用<a href="../../../../../api/SIMT-API/memory_access_functions/asc_ldcg.html">asc_ldcg</a>接口通过硬件保证缓存数据与GM数据一致性。</li></ul><p>上述解决方式会增加额外操作，影响整体运行效率。用户需要根据自身需求和实际场景，酌情选择是否需要使用上述方法。</p></article></div>',1)])])}const M=e(p,[["render",o]]);export{u as __pageData,M as default};
